<template>
  <div class="msg-action-bar">
    <!-- 操作按钮区域 -->
    <div v-if="role === MSG_ROLE_ASSISTANT" class="action-buttons">
      <!-- 重新生成按钮 -->
      <l-tooltip v-if="showRegenerate" :content="t('regenerate')" placement="bottom" :show-arrow="false" :disabled="hasAnyPopoverOpen" :auto-close="isMobile ? 500 : 0" >
        <div class="action-button" @click="handleRegenerate">
          <l-img src="/static/images/msg-ai-refresh.png" w="16px" h="16px" />
        </div>
      </l-tooltip>

      <!-- 复制按钮 -->
      <l-tooltip v-if="showCopy" :content="!showCopySuccess ? t('copy') :t('copied')" placement="bottom" :show-arrow="false" :disabled="hasAnyPopoverOpen" :auto-close="isMobile ? 500 : 0">
        <div class="action-button" @click="handleCopy">
          <l-img
            v-if="!showCopySuccess"
            src="/static/images/msg-ai-copy.png"
            w="16px"
            h="16px"
          />
          <l-img
            v-else
            src="/static/images/msg-ai-copy-s.png"
            w="16px"
            h="16px"
          />
        </div>
      </l-tooltip>

      <!-- 分享链接按钮 -->
      <l-tooltip v-if="showShare" :content="!showShareSuccess ? t('copyShareLink') : t('copied')" :auto-close="isMobile ? 500 : 0" placement="bottom" :show-arrow="false" :disabled="hasAnyPopoverOpen">
        <div class="action-button" @click="handleShare">
          <l-img
            v-if="!showShareLoading && !showShareSuccess"
            src="/static/images/msg-ai-share.png"
            w="16px"
            h="16px"
          />
          <el-icon
            v-else-if="showShareLoading"
            size="16px"
            class="loading-icon"
          >
            <Loading />
          </el-icon>
          <l-img
            v-else
            src="/static/images/msg-ai-copy-s.png"
            w="16px"
            h="16px"
          />
        </div>
      </l-tooltip>

      <!-- 点赞按钮 -->
      <l-tooltip
        v-if="showLike"
        ref="likeTooltipRef"
        :content="t('loveThis')"
        :auto-close="isMobile ? 500 : 0"
        placement="bottom"
        :show-arrow="false"
        :disabled="hasAnyPopoverOpen"
      >
        <div
          ref="likeButtonRef"
          class="action-button"
          @click="handleLike"
        >
          <l-img
            :src="buttonStates.isLiked ? '/static/images/msg-ai-s-well-written.png' : '/static/images/msg-ai-like.png'"
            w="16px"
            h="16px"
          />
        </div>
      </l-tooltip>

      <!-- 点赞弹窗 -->
      <el-popover
        placement="bottom"
        :width="231"
        trigger="manual"
        v-model:visible="popoverVisible.like"
        popper-class="feedback-popover"
        :show-arrow="false"
        :virtual-ref="likeButtonRef"
        :virtual-triggering="true"
      >

        <!-- 点赞反馈弹窗内容 -->
        <div class="feedback-container">
          <div
            v-for="item in likeOptions"
            :key="item.key"
            class="feedback-item"
            @click="handleFeedbackSelect('like', item)"
          >
            <div class="feedback-icon">
              <l-img :src="item.icon" w="14px" h="14px" />
            </div>
            <div class="feedback-text">{{ item.text }}</div>
          </div>
        </div>
      </el-popover>

      <!-- 点踩按钮 -->
      <l-tooltip
        v-if="showDislike"
        ref="dislikeTooltipRef"
        :content="t('needsImprovement')"
        :auto-close="isMobile ? 500 : 0"
        placement="bottom"
        :show-arrow="false"
        :disabled="hasAnyPopoverOpen"
      >
        <div
          ref="dislikeButtonRef"
          class="action-button"
          @click="handleDislike"
        >
          <l-img
            :src="buttonStates.isDisliked ? '/static/images/msg-ai-biased-answer.png' : '/static/images/msg-ai-no-like.png'"
            w="16px"
            h="16px"
          />
        </div>
      </l-tooltip>

      <!-- 点踩弹窗 -->
      <el-popover
        placement="bottom"
        :width="265"
        trigger="manual"
        v-model:visible="popoverVisible.dislike"
        popper-class="feedback-popover"
        :show-arrow="false"
        :virtual-ref="dislikeButtonRef"
        :virtual-triggering="true"
      >

        <!-- 点踩反馈弹窗内容 -->
        <div class="feedback-container">
          <div
            v-for="item in dislikeOptions"
            :key="item.key"
            class="feedback-item"
            @click="handleFeedbackSelect('dislike', item)"
          >
            <div class="feedback-icon">
              <l-img :src="item.icon" w="14px" h="14px" />
            </div>
            <div class="feedback-text">{{ item.text }}</div>
          </div>
        </div>
      </el-popover>

      <!-- 更多操作按钮 -->
      <l-tooltip
        v-if="showMore"
        ref="moreTooltipRef"
        :content="t('more')"
        :auto-close="isMobile ? 500 : 0"
        placement="bottom"
        :show-arrow="false"
        :disabled="hasAnyPopoverOpen"
      >
        <div
          ref="moreButtonRef"
          class="action-button"
          @click="handleMore"
        >
          <l-img src="/static/images/msg-ai-more.png" w="16px" h="16px" />
        </div>
      </l-tooltip>

      <!-- 更多操作弹窗 -->
      <el-popover
        placement="bottom"
        :width="230"
        trigger="manual"
        v-model:visible="popoverVisible.more"
        popper-class="feedback-popover"
        :show-arrow="false"
        :virtual-ref="moreButtonRef"
        :virtual-triggering="true"
      >

        <!-- 更多操作弹窗内容 -->
        <div class="feedback-container">
          <div class="feedback-item" @click="handleReportIssue">
            <div class="feedback-icon">
              <l-img src="/static/images/msg-ai-report-issue.png" w="14px" h="14px" />
            </div>
            <div class="feedback-text">{{ t('reportIssue') }}</div>
          </div>
        </div>
      </el-popover>
    </div>
    <div v-else class="action-buttons" style="justify-content: flex-end;">
      <!-- 分享链接按钮 -->
      <l-tooltip v-if="showShare" :content="!showShareSuccess ? t('copyShareLink') : t('copied')" placement="bottom" :show-arrow="false" :disabled="hasAnyPopoverOpen" :auto-close="isMobile ? 500 : 0">
        <div @click="handleShare" class="action-button">
          <l-img
            v-if="!showShareLoading && !showShareSuccess"
            src="/static/images/msg-ai-share.png"
            w="16px"
            h="16px"
          />
          <el-icon
            v-else-if="showShareLoading"
            :size="pxToRem('16px')"
            class="loading-icon"
          >
            <Loading />
          </el-icon>
          <l-img
            v-else
            src="/static/images/msg-ai-copy-s.png"
            w="16px"
            h="16px"
          />
        </div>
      </l-tooltip>
      <!-- 复制按钮 -->
      <l-tooltip v-if="showCopy" :content="!showCopySuccess ? t('copy') :t('copied')" placement="bottom" :show-arrow="false" :disabled="hasAnyPopoverOpen" :auto-close="isMobile ? 500 : 0">
        <div class="action-button" @click="handleCopy">
          <l-img
            v-if="!showCopySuccess"
            src="/static/images/msg-ai-copy.png"
            w="16px"
            h="16px"
          />
          <l-img
            v-else
            src="/static/images/msg-ai-copy-s.png"
            w="16px"
            h="16px"
          />
        </div>
      </l-tooltip>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRoute } from 'vue-router';
import { ElMessage, ElIcon } from 'element-plus';
import { Loading } from '@element-plus/icons-vue';
import { ApiShare } from '@/api/api-share';
import { copy, handleNotYet } from '@/utils/util';
import { ROUTER_PATHS } from '@/router/constants';
import LImg from '@/components/l-img.vue';
import LTooltip from '../l-tooltip.vue';
import { MSG_ROLE_USER, MSG_ROLE_ASSISTANT, MESSAGE_STATUS } from '@/types/msg.ts';
import { useDeviceDetection } from '@/utils/device-detector';
import { pxToRem } from '@/utils/px-to-rem';



const { t } = useI18n();
const route = useRoute();
const { isMobile } = useDeviceDetection();

// 组件props
const props = defineProps({
  // 消息内容，用于复制
  content: {
    type: String,
    default: ''
  },
  // 消息ID，用于分享链接
  messageId: {
    type: [String, Number],
    default: ''
  },
  // 消息角色
  role: {
    type: String,
    default: ''
  },
  // 是否显示重新生成按钮
  showRegenerate: {
    type: Boolean,
    default: true
  },
  // 是否显示复制按钮
  showCopy: {
    type: Boolean,
    default: true
  },
  // 是否显示分享按钮
  showShare: {
    type: Boolean,
    default: true
  },
  // 是否显示点赞按钮
  showLike: {
    type: Boolean,
    default: true
  },
  // 是否显示点踩按钮
  showDislike: {
    type: Boolean,
    default: true
  },
  // 是否显示更多按钮
  showMore: {
    type: Boolean,
    default: true
  },
});

// 组件事件
const emit = defineEmits(['onRegenerate', 'onFeedback', 'onReportIssue']);

// 按钮状态
const buttonStates = ref({
  isLiked: false,
  isDisliked: false
});

// 复制和分享状态
const showCopySuccess = ref(false);
const showShareSuccess = ref(false);
const showShareLoading = ref(false);

// 弹窗显示状态
const popoverVisible = ref({
  like: false,
  dislike: false,
  more: false
});

// 公共状态：检查是否有任何弹窗打开
const hasAnyPopoverOpen = computed(() => {
  return popoverVisible.value.like || popoverVisible.value.dislike || popoverVisible.value.more;
});

// 按钮和tooltip引用
const likeButtonRef = ref(null);
const dislikeButtonRef = ref(null);
const moreButtonRef = ref(null);
const likeTooltipRef = ref(null);
const dislikeTooltipRef = ref(null);
const moreTooltipRef = ref(null);

// 点赞选项配置
const likeOptions = computed(() => [
  {
    key: 'helpful',
    text: t('helpfulAnswer'),
    icon: '/static/images/msg-ai-helpful.png'
  },
  {
    key: 'accurate',
    text: t('accurateInformation'),
    icon: '/static/images/msg-ai-accurate.png'
  },
  {
    key: 'wellWritten',
    text: t('wellWrittenResponse'),
    icon: '/static/images/msg-ai-written.png'
  },
  {
    key: 'funny',
    text: t('funnyResponse'),
    icon: '/static/images/msg-ai-funny.png'
  },
  {
    key: 'goodMemory',
    text: t('goodUseOfMemory'),
    icon: '/static/images/msg-ai-good-memory.png'
  }
]);

// 点踩选项配置
const dislikeOptions = computed(() => [
  {
    key: 'wantedElse',
    text: t('wantedSomethingElse'),
    icon: '/static/images/msg-ai-wanted.png'
  },
  {
    key: 'incorrect',
    text: t('incorrectAnswer'),
    icon: '/static/images/msg-ai-incorrect.png'
  },
  {
    key: 'biased',
    text: t('biasedAnswer'),
    icon: '/static/images/msg-ai-biased.png'
  },
  {
    key: 'wantedImage',
    text: t('wantedImage'),
    icon: '/static/images/msg-ai-wanted-image.png'
  },
  {
    key: 'badStyle',
    text: t('badStyleTone'),
    icon: '/static/images/msg-ai-bad.png'
  },
  {
    key: 'wantedSearch',
    text: t('wantedToSearch'),
    icon: '/static/images/msg-ai-wanted-search.png'
  },
  {
    key: 'incorrectMemory',
    text: t('incorrectMemory'),
    icon: '/static/images/msg-ai-incorrect-memory.png'
  }
]);

// 重新生成处理
const handleRegenerate = () => {
  handleNotYet();
  return;
  emit('onRegenerate');
};

// 复制处理
const handleCopy = () => {
  if (!props.content) {
    console.warn('No content to copy');
    return;
  }

  // 使用项目封装的复制函数
  copy(props.content);

  // 显示成功状态
  showCopySuccess.value = true;

  // 1秒后恢复原状
  setTimeout(() => {
    showCopySuccess.value = false;
  }, 1000);
};

// 分享处理
const handleShare = async () => {
  // 如果正在加载或已成功，则不重复处理
  if (showShareLoading.value || showShareSuccess.value) {
    return;
  }

  try {
    // 从当前路由获取sessionId
    const sessionId = route.params.sessionId;

    if (!sessionId) {
      console.warn('No session to share');
      return;
    }

    // 显示加载状态
    showShareLoading.value = true;

    const response = await ApiShare.createSessionShare(parseInt(sessionId));

    if (response.code === 200) {
      const shareUrl = `${window.location.origin}${ROUTER_PATHS.SHARE}/${response.data.share_id}`;

      // 使用项目封装的复制函数
      copy(shareUrl);

      // 隐藏加载状态，显示成功状态
      showShareLoading.value = false;
      showShareSuccess.value = true;
      ElMessage.success(t('shareSuccessTip'));

      // 1秒后恢复原状
      setTimeout(() => {
        showShareSuccess.value = false;
      }, 1000);
    } else {
      throw new Error(response.message);
    }
  } catch (error) {
    console.error('Share failed:', error);
    // 隐藏加载状态
    showShareLoading.value = false;
  }
};

// 点赞处理
const handleLike = () => {

  handleNotYet();
  return;
  // 如果已经选择了点赞，再次点击取消选择
  if (buttonStates.value.isLiked) {
    buttonStates.value.isLiked = false;
    return;
  }

  // 显示点赞反馈弹窗
  popoverVisible.value.like = true;
};

// 点踩处理
const handleDislike = () => {

  handleNotYet();
  return;
  // 如果已经选择了点踩，再次点击取消选择
  if (buttonStates.value.isDisliked) {
    buttonStates.value.isDisliked = false;
    return;
  }

  // 显示点踩反馈弹窗
  popoverVisible.value.dislike = true;
};

// 更多操作处理
const handleMore = () => {

  handleNotYet();
  return;
  popoverVisible.value.more = !popoverVisible.value.more;
};

// 反馈选择处理
const handleFeedbackSelect = (type, item) => {
  console.log(`Feedback selected: ${type} - ${item.key}`);

  // 设置按钮状态
  if (type === 'like') {
    // 如果之前有点踩，先取消点踩
    if (buttonStates.value.isDisliked) {
      buttonStates.value.isDisliked = false;
    }
    buttonStates.value.isLiked = true;
  } else if (type === 'dislike') {
    // 如果之前有点赞，先取消点赞
    if (buttonStates.value.isLiked) {
      buttonStates.value.isLiked = false;
    }
    buttonStates.value.isDisliked = true;
  }

  // 发送反馈事件到父组件
  emit('onFeedback', {
    type: type,
    option: item.key,
    messageId: props.messageId
  });

  // 关闭弹窗
  popoverVisible.value[type] = false;

  // 控制台输出成功信息
  console.log('Feedback submitted successfully');
};

// 举报问题处理
const handleReportIssue = () => {
  emit('onReportIssue', {
    messageId: props.messageId
  });

  // 关闭弹窗
  popoverVisible.value.more = false;

  console.log('Report submitted successfully');
};

</script>

